preConditionHook:
// EL: adverseDown = countif(c < o, adverseBars), adverseUp the mirror
// (lowercase as the feature register writes it).
// CountIF counts bars 0..N-1 INCLUDING the current bar and the counted
// condition is a true series (EL_FEATURES `countif`, VERIFIED). The counted
// condition is on PRICES, which have real history back to the chart start, so
// no zero-filled variable mirror is needed -- the arrangement
// OppositeBodyCountInWindow and SpikeWithoutPullback use.
//
// A tie bar (close equal to open within the EL tolerance) counts for neither.
// The counts are EL numeric variables, so they are doubles here.
//
// The source writes "count = adverseBars"; since CountIF over adverseBars bars
// can never exceed adverseBars, >= is the same test without a float equality.
adverseDown = 0.0;
adverseUp = 0.0;
for (int i = 0; i < (int)adverseBars; ++i) {
    if (el_lt(close[i], open[i])) adverseDown += 1;
    if (el_gt(close[i], open[i])) adverseUp += 1;
}
